/// Routes a download-button tap through [cubit]'s own [download] method
/// (`downloadPdf`/`downloadRawData`), then surfaces
/// `ExportJobCubit.lastDownloadFailure` — if the attempt left one behind —
/// as an inline `SnackBar`, mirroring `_onExportTap`'s own create-failure
/// pattern (`meus_registros_screen.dart`). Never touches [state]/rebuilds
/// the sheet's own job-status content (Boundaries) — the failure is read
/// off, and cleared from, the cubit's plain field, not folded into
/// [ExportJobState].
Future<void> _handleDownload(
  BuildContext context,
  ExportJobCubit cubit,
  Future<void> Function() download,
) async {
  await download();
  final failure = cubit.lastDownloadFailure;
  if (failure == null) {
    return;
  }
  cubit.lastDownloadFailure = null;
  if (!context.mounted) {
    return;
  }
  ScaffoldMessenger.of(context)
      .showSnackBar(SnackBar(content: Text(failure.message)));
}

